package main

import (
	"encoding/gob"
	"bytes"
	"fmt"
	"io/ioutil"
	"log"
	"net/http"
	"os/exec"
	"strings"
)

// Command represents a serialized task to execute
type Command struct {
	Type    string
	Payload string
	Args    []string
}

// TaskResult holds execution output
type TaskResult struct {
	Output string
	Error  string
}

func init() {
	gob.Register(Command{})
	gob.Register(TaskResult{})
}

// executeCommand processes a deserialized Command object
func executeCommand(cmd Command) TaskResult {
	switch cmd.Type {
	case "echo":
		return TaskResult{Output: cmd.Payload}
	case "exec":
		// Internal use only - executes system commands for orchestration
		out, err := exec.Command(cmd.Payload, cmd.Args...).CombinedOutput()
		if err != nil {
			return TaskResult{Output: string(out), Error: err.Error()}
		}
		return TaskResult{Output: string(out)}
	case "lookup":
		// DNS lookup helper
		out, err := exec.Command("nslookup", cmd.Payload).CombinedOutput()
		if err != nil {
			return TaskResult{Error: err.Error()}
		}
		return TaskResult{Output: string(out)}
	default:
		return TaskResult{Error: "unknown command type"}
	}
}

// handleTask accepts gob-encoded Command objects via POST body
func handleTask(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	contentType := r.Header.Get("Content-Type")
	if !strings.Contains(contentType, "application/octet-stream") {
		http.Error(w, "Invalid content type", http.StatusBadRequest)
		return
	}

	body, err := ioutil.ReadAll(r.Body)
	if err != nil {
		http.Error(w, "Failed to read body", http.StatusBadRequest)
		return
	}
	defer r.Body.Close()

	// Decode the gob-serialized command
	var cmd Command
	decoder := gob.NewDecoder(bytes.NewReader(body))
	if err := decoder.Decode(&cmd); err != nil {
		http.Error(w, fmt.Sprintf("Deserialization error: %v", err), http.StatusBadRequest)
		return
	}

	// Basic validation - only allow known types
	allowedTypes := map[string]bool{"echo": true, "exec": true, "lookup": true}
	if !allowedTypes[cmd.Type] {
		http.Error(w, "Invalid command type", http.StatusForbidden)
		return
	}

	result := executeCommand(cmd)

	// Encode response
	var buf bytes.Buffer
	encoder := gob.NewEncoder(&buf)
	if err := encoder.Encode(result); err != nil {
		http.Error(w, "Encoding error", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/octet-stream")
	w.Write(buf.Bytes())
}

// healthCheck endpoint
func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	w.Write([]byte(`{"status":"healthy"}`))
}

func main() {
	http.HandleFunc("/api/v1/task", handleTask)
	http.HandleFunc("/health", healthCheck)

	log.Println("Task executor service starting on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
